const DIST_TOLERANCE_MI = 2; // slack for centroid approximation

function clampInt(v, lo, hi, dflt) {
  const n = Number(v);
  if (!Number.isFinite(n)) return dflt;
  return Math.min(hi, Math.max(lo, Math.round(n)));
}

function zip5(z) {
  const d = String(z || "").replace(/\D/g, "");
  return d.length >= 5 ? d.slice(0, 5) : null;
}

function haversineMi(a, b) {
  const R = 3958.8; // earth radius, miles
  const toRad = (x) => (x * Math.PI) / 180;
  const dLat = toRad(b[0] - a[0]);
  const dLng = toRad(b[1] - a[1]);
  const s =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(a[0])) * Math.cos(toRad(b[0])) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(s));
}

function starPoints(stars, weight) {
  if (stars == null) return 0;
  return (stars / 5) * weight;
}

export function scoreQuiz(answers, facilities) {
  const a = answers || {};
  const priorities = {
    staffing: clampInt(a.priorities && a.priorities.staffing, 0, 2, 0),
    quality: clampInt(a.priorities && a.priorities.quality, 0, 2, 0),
    inspection: clampInt(a.priorities && a.priorities.inspection, 0, 2, 0),
  };
  const needs = Object.assign(
    { dementia: false, rehab: false, ventilator: false, bariatric: false, dialysis: false },
    a.needs || {}
  );
  const minOverall = clampInt(a.minOverall, 1, 5, 1);
  const maxDist = Number(a.maxDistanceMiles);
  const maxDistanceMiles = Number.isFinite(maxDist) && maxDist > 0 ? maxDist : 25;

  const Ws = 5 + 10 * priorities.staffing;
  const Wq = 5 + 10 * priorities.quality;
  const Wi = 4 + 8 * priorities.inspection;
  const RAW_MAX = 30 + Ws + Wq + Wi;
  const scale = 100 / RAW_MAX;

  const userZip = zip5(a.zip);
  const userGeo = userZip
    ? ZIP_CENTROIDS[userZip] || PREFIX3_CENTROIDS[userZip.slice(0, 3)] || null
    : null;
  const userGeoApprox = userZip && userGeo && !ZIP_CENTROIDS[userZip];
  const activeNeeds = Object.keys(needs).filter((k) => needs[k]);
  const NEED_LABELS = {
    dementia: "dementia/memory care",
    rehab: "rehabilitation",
    ventilator: "ventilator care",
    bariatric: "bariatric care",
    dialysis: "dialysis",
  };

  const out = [];

  for (const f of facilities || []) {
    const factors = [];
    let raw = 0;

    // ---- hard filter: minimum overall stars ----
    const overall = f.overall_rating;
    if (overall == null) {
      if (minOverall > 1) continue; // unverifiable -> cannot satisfy a minimum
      factors.push({
        label: "Overall rating",
        points: 0,
        detail: "No CMS overall star rating published for this facility.",
      });
    } else {
      if (overall < minOverall) continue;
      const p = starPoints(overall, 30);
      raw += p;
      factors.push({
        label: "Overall rating",
        points: Math.round(p * scale),
        detail: `CMS overall ${overall} of 5 stars.`,
      });
    }

    // ---- hard filter: distance (approximate, skipped if ZIP unknown) ----
    let distMi = null;
    if (userGeo) {
      const fz = zip5(f.zip);
      const fGeo = fz ? ZIP_CENTROIDS[fz] || null : null;
      if (fGeo) {
        distMi = haversineMi(userGeo, fGeo);
        if (distMi > maxDistanceMiles + DIST_TOLERANCE_MI) continue;
      }
    }

    // ---- weighted components ----
    const comp = [
      ["Staffing", f.staffing_rating, Ws, "CMS staffing"],
      ["Quality", f.quality_rating, Wq, "CMS quality-measures"],
      ["Health inspection", f.health_inspection_rating, Wi, "CMS health inspection"],
    ];
    for (const [label, stars, weight, cmsLabel] of comp) {
      if (stars == null) {
        factors.push({
          label,
          points: 0,
          detail: `No ${cmsLabel} star rating published by CMS — scored as 0, not estimated.`,
        });
      } else {
        const p = starPoints(stars, weight);
        raw += p;
        factors.push({
          label,
          points: Math.round(p * scale),
          detail: `${cmsLabel} ${stars} of 5 stars (your priority: ${
            label === "Staffing" ? priorities.staffing
            : label === "Quality" ? priorities.quality : priorities.inspection
          }/2).`,
        });
      }
    }

    // ---- distance factor (informational) ----
    if (distMi != null) {
      factors.push({
        label: "Distance",
        points: 0,
        detail: `About ${distMi < 1 ? "<1" : Math.round(distMi)} miles away` +
          (userGeoApprox ? " (approximate — your ZIP estimated from nearby ZIPs)." : " (ZIP-centroid estimate)."),
      });
    } else {
      factors.push({
        label: "Distance",
        points: 0,
        detail: userZip
          ? "Your ZIP isn't in our NY/NJ coverage map — distance not filtered."
          : "No ZIP entered — distance not filtered.",
      });
    }

    // ---- special needs (never scored — no CMS source; verify by phone) ----
    if (activeNeeds.length) {
      factors.push({
        label: "Special needs",
        points: 0,
        detail:
          "CMS data doesn't list specialty services; please verify " +
          activeNeeds.map((k) => NEED_LABELS[k]).join(", ") +
          ` directly at ${f.phone || "the facility"}.`,
      });
    }

    out.push({ facility: f, score: Math.round(raw * scale), factors });
  }

  out.sort((x, y) => {
    if (y.score !== x.score) return y.score - x.score;
    const oy = y.facility.overall_rating || 0;
    const ox = x.facility.overall_rating || 0;
    if (oy !== ox) return oy - ox;
    return String(x.facility.ccn).localeCompare(String(y.facility.ccn));
  });

  return out;
}

export { ZIP_CENTROIDS, PREFIX3_CENTROIDS, haversineMi };

