function zip5s(z) {
  const d = String(z || "").replace(/\D/g, "");
  return d.length >= 5 ? d.slice(0, 5) : null;
}

function userGeoFor(zip) {
  const z5 = zip5s(zip);
  if (!z5) return null;
  return ZIP_CENTROIDS[z5] || PREFIX3_CENTROIDS[z5.slice(0, 3)] || null;
}

// Deterministic top-n, same scorer as the PWA. Returns facts-ready entries:
// { ccn, name, city, state, zip, phone, score, distance_miles, data_as_of, facts }
export function rankTop(answers, n = 10) {
  const ranked = scoreQuiz(answers || {}, FACILITIES);
  const ug = userGeoFor(answers && answers.zip);
  return ranked.slice(0, Math.max(1, n || 10)).map((r) => {
    const f = r.facility || {};
    let distMi = null;
    if (ug) {
      const fz = zip5s(f.zip);
      const fg = fz ? ZIP_CENTROIDS[fz] || null : null;
      if (fg) distMi = Math.round(haversineMi(ug, fg) * 10) / 10;
    }
    return {
      ccn: String(f.ccn || ""),
      name: String(f.name || ""),
      address: f.address || null,
      ownership: f.ownership || null,
      city: f.city || null,
      state: f.state || null,
      zip: f.zip || null,
      phone: f.phone || null,
      score: typeof r.score === "number" ? Math.round(r.score) : null,
      distance_miles: distMi,
      data_as_of: f.data_as_of || null,
      factors: Array.isArray(r.factors) ? r.factors : [],
      facts: {
        overall_rating: f.overall_rating,
        staffing_rating: f.staffing_rating,
        quality_rating: f.quality_rating,
        health_inspection_rating: f.health_inspection_rating,
        beds: f.beds,
        distance_miles: distMi,
      },
    };
  });
}

export const FACILITY_COUNT = FACILITIES.length;
